from pathlib import Path
import base64, hashlib, io, json, zipfile
root = Path('products/distribution/sqlite-original-regression-exercise')
for path in sorted(root.rglob('*')):
    if not path.is_file():
        continue
    content = path.read_bytes()
    print(json.dumps({'path': str(path), 'bytes': len(content), 'sha256': hashlib.sha256(content).hexdigest()}))
    if path.name.endswith('.zip.b64'):
        try:
            archive = base64.b64decode(b''.join(content.split()), validate=True)
            with zipfile.ZipFile(io.BytesIO(archive)) as package:
                print(json.dumps({'archive_sha256': hashlib.sha256(archive).hexdigest(), 'members': package.namelist(), 'first_bad_crc': package.testzip()}))
        except (ValueError, OSError, zipfile.BadZipFile) as error:
            print(json.dumps({'archive_read_error': str(error)}))
    if path.name == 'private-evaluation-verification.json':
        receipt = json.loads(content)
        print(json.dumps({key: value for key, value in receipt.items() if key not in {'runs', 'stdout', 'stderr'}}, ensure_ascii=False)[:2200])
        for run in receipt.get('runs', []):
            print(json.dumps({key: run[key] for key in ('mode', 'expected_exit', 'actual_exit', 'failing_cases', 'passed') if key in run}))
